// Des: Layered per-group, per-site, per-path rules over the main config
// Flo: pick best site rule by host (exact beats wildcard) > apply group > site > matching path rules on a copy of Conf > refuse unknown keys, wrong types, values above global caps
// I/O: Conf + host + path (caller) > merged Conf copy and a list of where each value came from; siteChek validates every rule at load
// ===================================================================
const std = @import("std"); const memz = std.mem; const cfgz = @import("cf-conf-load.zig");
const CF = .{ .meta = @as([]const []const u8, &.{ "name", "host", "grup", "enab", "note", "path", "path_rule_list" }), .allw = @as([]const []const u8, &.{ "rate_host_seco", "rate_jitt_pctz", "rate_429z_pctz", "retr_afte_enab", "retr_back_seco", "retr_code_list", "retr_cont_maxz", "fetc_time_seco", "fetc_body_maxz", "fetc_redi_maxz", "pdfz_size_maxz", "tier_star", "tier_maxz", "tier_skip_list", "tier_t1fz", "tier_ages", "vend_orde", "vend_bann_list", "capz_cred_pagz", "geoz_code_dflt", "apiz_prob_enab", "apiz_prob_maxz", "apiz_path_list", "shel_text_minz", "shel_mark_list", "judg_bloc_list", "judg_must_list", "judg_text_minz", "judg_fiel_requ", "brow_enab", "brow_time_seco", "brow_wait_msec", "brow_sele_wait", "brow_scrl_maxz", "brow_clic_text", "brow_step_file", "brow_step_maxz", "brow_blok_resz", "cons_sele_list", "acct_page_maxz", "acct_gapz_mult", "strm_time_seco", "strm_frme_maxz", "foll_maxz", "foll_incl_list", "foll_excl_list", "revi_star_seco", "revi_floo_seco", "revi_capz_seco", "extr_pref_list", "ocrz_enab" }), .ceil = @as([]const []const u8, &.{ "retr_cont_maxz", "fetc_time_seco", "fetc_body_maxz", "fetc_redi_maxz", "pdfz_size_maxz", "tier_maxz", "apiz_prob_maxz", "brow_time_seco", "brow_scrl_maxz", "brow_step_maxz", "acct_page_maxz", "strm_time_seco", "strm_frme_maxz" }), .tier = @as([]const []const u8, &.{ "own", "brow", "plain", "rend", "prem" }), .kind = @as([]const []const u8, &.{ "ldjs", "next", "json", "text" }), .vend = @as([]const []const u8, &.{ "deco", "zenr", "brig" }) };
pub const Diag = struct { text: []const u8 = "" };
pub const Srcz = struct { keyz: []const u8, from: []const u8 };
fn fail(diag: *Diag, comptime fmtz: []const u8, args: anytype) anyerror { diag.text = std.fmt.allocPrint(std.heap.page_allocator, fmtz, args) catch fmtz; return error.BadConfig; }
fn listFind(list: []const []const u8, name: []const u8) bool { for (list) |item| { if (memz.eql(u8, item, name)) return true; } return false; }
fn typeList(comptime Type: type) bool { const info = @typeInfo(Type); return info == .pointer and info.pointer.size == .slice and info.pointer.child != u8; }
pub fn globMach(patn: []const u8, text: []const u8) bool { var pind: usize = 0; var tind: usize = 0; var star: ?usize = null; var mark: usize = 0; while (tind < text.len) { if (pind < patn.len and (patn[pind] == '?' or patn[pind] == text[tind])) { pind += 1; tind += 1; } else if (pind < patn.len and patn[pind] == '*') { star = pind; mark = tind; pind += 1; } else if (star) |sidx| { pind = sidx + 1; mark += 1; tind = mark; } else return false; } while (pind < patn.len and patn[pind] == '*') pind += 1; return pind == patn.len; }
pub fn hostMach(patn: []const u8, host: []const u8) i32 { if (std.ascii.eqlIgnoreCase(patn, host)) return 10000 + @as(i32, @intCast(patn.len)); if (patn.len > 2 and memz.startsWith(u8, patn, "*.")) { const tail = patn[1..]; if (host.len > tail.len and std.ascii.eqlIgnoreCase(host[host.len - tail.len ..], tail)) return 100 + @as(i32, @intCast(tail.len)); } return -1; }
fn ruleText(rule: std.json.Value, keyz: []const u8) []const u8 { if (rule != .object) return ""; const valu = rule.object.get(keyz) orelse return ""; if (valu != .string) return ""; return valu.string; }
fn fielAppl(comptime Type: type, dest: *Type, orig: Type, valu: std.json.Value, addz: bool, aren: std.mem.Allocator, keyz: []const u8, diag: *Diag) !void { const nuvo = std.json.parseFromValueLeaky(Type, aren, valu, .{ .allocate = .alloc_always }) catch return fail(diag, "key '{s}' has the wrong type", .{keyz}); if (addz) { if (comptime typeList(Type)) { dest.* = try memz.concat(aren, @typeInfo(Type).pointer.child, &.{ dest.*, nuvo }); } else return fail(diag, "key '{s}_adds' only works on list keys", .{keyz}); } else dest.* = nuvo; if (comptime @typeInfo(Type) == .int) { if (listFind(CF.ceil, keyz) and nuvo > orig) return fail(diag, "key '{s}' = {d} is above the global value {d}; a rule can only lower it", .{ keyz, nuvo, orig }); if (memz.eql(u8, keyz, "capz_cred_pagz") and orig > 0 and (nuvo == 0 or nuvo > orig)) return fail(diag, "key 'capz_cred_pagz' must stay between 1 and the global {d}", .{orig}); } }
pub fn ruleAppl(aren: std.mem.Allocator, outp: *cfgz.Conf, base: cfgz.Conf, rule: std.json.Value, from: []const u8, srcs: *std.ArrayList(Srcz), diag: *Diag) !void { if (rule != .object) return fail(diag, "{s} is not an object", .{from}); var iter = rule.object.iterator(); while (iter.next()) |item| { const keyz = item.key_ptr.*; if (listFind(CF.meta, keyz)) continue; var name = keyz; var addz = false; if (memz.endsWith(u8, keyz, "_adds")) { name = keyz[0 .. keyz.len - 5]; addz = true; } if (!listFind(CF.allw, name)) return fail(diag, "{s}: key '{s}' is not allowed in a rule", .{ from, keyz }); var done = false; inline for (@typeInfo(cfgz.Conf).@"struct".field_names, @typeInfo(cfgz.Conf).@"struct".field_types) |fnam, ftyp| { if (!done and memz.eql(u8, fnam, name)) { try fielAppl(ftyp, &@field(outp, fnam), @field(base, fnam), item.value_ptr.*, addz, aren, keyz, diag); done = true; } } if (!done) return fail(diag, "{s}: key '{s}' has no setting", .{ from, keyz }); try srcs.append(aren, .{ .keyz = keyz, .from = from }); } }
fn merg(aren: std.mem.Allocator, conf: cfgz.Conf, host: []const u8, path: []const u8, srcs: *std.ArrayList(Srcz), diag: *Diag) !cfgz.Conf { var outp = conf; const ruleList = conf.site_rule_list orelse return outp; if (ruleList != .array) return outp; var best: ?std.json.Value = null; var scor: i32 = -1; for (ruleList.array.items) |cand| { if (cand != .object) continue; if (cand.object.get("enab")) |flag| { if (flag == .bool and !flag.bool) continue; } const hostList = cand.object.get("host") orelse continue; if (hostList != .array) continue; for (hostList.array.items) |patn| { if (patn != .string) continue; const valu = hostMach(patn.string, host); if (valu > scor) { scor = valu; best = cand; } } } const rule = best orelse return outp; if (conf.grup_rule_mapz) |mapz| { if (mapz == .object) { const gnam = ruleText(rule, "grup"); if (mapz.object.get(gnam)) |grup| { try ruleAppl(aren, &outp, conf, grup, try std.fmt.allocPrint(aren, "group {s}", .{gnam}), srcs, diag); } } } try ruleAppl(aren, &outp, conf, rule, try std.fmt.allocPrint(aren, "site {s}", .{ruleText(rule, "name")}), srcs, diag); if (rule.object.get("path_rule_list")) |plst| { if (plst == .array) { for (plst.array.items) |prul| { const patn = ruleText(prul, "path"); if (patn.len > 0 and globMach(patn, path)) try ruleAppl(aren, &outp, conf, prul, try std.fmt.allocPrint(aren, "path {s}", .{patn}), srcs, diag); } } } return outp; }
pub fn siteConf(aren: std.mem.Allocator, conf: cfgz.Conf, host: []const u8, path: []const u8) !cfgz.Conf { if (conf.site_rule_list == null) return conf; var srcs: std.ArrayList(Srcz) = .empty; var diag: Diag = .{}; return merg(aren, conf, host, path, &srcs, &diag); }
pub fn siteExpl(aren: std.mem.Allocator, conf: cfgz.Conf, host: []const u8, path: []const u8, srcs: *std.ArrayList(Srcz)) !cfgz.Conf { var diag: Diag = .{}; return merg(aren, conf, host, path, srcs, &diag); }
pub fn valuText(aren: std.mem.Allocator, conf: cfgz.Conf, keyz: []const u8) ![]const u8 { inline for (@typeInfo(cfgz.Conf).@"struct".field_names, @typeInfo(cfgz.Conf).@"struct".field_types) |fnam, ftyp| { if (memz.eql(u8, fnam, keyz)) { if (comptime @typeInfo(ftyp) != .optional) return std.json.Stringify.valueAlloc(aren, @field(conf, fnam), .{}); } } return ""; }
fn valiMerg(conf: cfgz.Conf, from: []const u8, diag: *Diag) !void { cfgz.confChek(conf) catch return fail(diag, "{s}: the merged settings are not valid (range or name)", .{from}); if (!listFind(CF.tier, conf.tier_star)) return fail(diag, "{s}: tier_star must be own, brow, plain, rend or prem", .{from}); if (conf.tier_maxz > 4) return fail(diag, "{s}: tier_maxz must be 0 to 4", .{from}); if (conf.rate_jitt_pctz > 100) return fail(diag, "{s}: rate_jitt_pctz must be 0 to 100", .{from}); if (conf.rate_429z_pctz < 10 or conf.rate_429z_pctz > 1000) return fail(diag, "{s}: rate_429z_pctz must be 10 to 1000", .{from}); for (conf.retr_code_list) |code| { if (code < 100 or code > 599) return fail(diag, "{s}: retr_code_list holds a bad status {d}", .{ from, code }); } for (conf.extr_pref_list) |kind| { if (!listFind(CF.kind, kind)) return fail(diag, "{s}: extr_pref_list has unknown kind '{s}'", .{ from, kind }); } for (conf.vend_bann_list) |name| { if (!listFind(CF.vend, name)) return fail(diag, "{s}: vend_bann_list has unknown vendor '{s}'", .{ from, name }); } for (conf.tier_skip_list) |name| { if (!listFind(CF.tier, name)) return fail(diag, "{s}: tier_skip_list has unknown tier '{s}'", .{ from, name }); } }
fn patnGood(patn: []const u8) bool { if (patn.len == 0 or memz.findAny(u8, patn, " /\\") != null) return false; if (memz.findScalar(u8, patn, '*')) |star| { return star == 0 and patn.len > 2 and patn[1] == '.' and memz.findScalarPos(u8, patn, 1, '*') == null; } return true; }
pub fn siteChek(conf: cfgz.Conf, diag: *Diag) !void { var arna = std.heap.ArenaAllocator.init(std.heap.page_allocator); defer arna.deinit(); const aren = arna.allocator(); var srcs: std.ArrayList(Srcz) = .empty; if (conf.grup_rule_mapz) |mapz| { if (mapz != .object) return fail(diag, "grup_rule_mapz must be an object", .{}); var iter = mapz.object.iterator(); while (iter.next()) |item| { var copy = conf; const from = try std.fmt.allocPrint(aren, "group {s}", .{item.key_ptr.*}); try ruleAppl(aren, &copy, conf, item.value_ptr.*, from, &srcs, diag); try valiMerg(copy, from, diag); } } const ruleList = conf.site_rule_list orelse return; if (ruleList != .array) return fail(diag, "site_rule_list must be a list", .{}); var seen: std.ArrayList([]const u8) = .empty; for (ruleList.array.items) |rule| { if (rule != .object) return fail(diag, "site_rule_list holds an item that is not an object", .{}); const name = ruleText(rule, "name"); if (name.len == 0) return fail(diag, "a site rule has no name", .{}); if (listFind(seen.items, name)) return fail(diag, "site rule name '{s}' is used twice", .{name}); try seen.append(aren, name); const hostList = rule.object.get("host") orelse return fail(diag, "site {s}: host list missing", .{name}); if (hostList != .array or hostList.array.items.len == 0) return fail(diag, "site {s}: host must be a non-empty list", .{name}); for (hostList.array.items) |patn| { if (patn != .string or !patnGood(patn.string)) return fail(diag, "site {s}: bad host pattern (use name.tld or *.name.tld)", .{name}); } var copy = conf; const gnam = ruleText(rule, "grup"); if (gnam.len > 0) { const mapz = conf.grup_rule_mapz orelse return fail(diag, "site {s}: group '{s}' does not exist", .{ name, gnam }); const grup = mapz.object.get(gnam) orelse return fail(diag, "site {s}: group '{s}' does not exist", .{ name, gnam }); try ruleAppl(aren, &copy, conf, grup, try std.fmt.allocPrint(aren, "group {s}", .{gnam}), &srcs, diag); } const from = try std.fmt.allocPrint(aren, "site {s}", .{name}); try ruleAppl(aren, &copy, conf, rule, from, &srcs, diag); try valiMerg(copy, from, diag); if (rule.object.get("path_rule_list")) |plst| { if (plst != .array) return fail(diag, "site {s}: path_rule_list must be a list", .{name}); for (plst.array.items) |prul| { const patn = ruleText(prul, "path"); if (patn.len == 0) return fail(diag, "site {s}: a path rule has no path", .{name}); var cop2 = copy; const fro2 = try std.fmt.allocPrint(aren, "site {s} path {s}", .{ name, patn }); try ruleAppl(aren, &cop2, conf, prul, fro2, &srcs, diag); try valiMerg(cop2, fro2, diag); } } } }
fn ruleTrue(rule: std.json.Value, keyz: []const u8) bool { if (rule != .object) return false; if (rule.object.get(keyz)) |valu| { if (valu == .bool and valu.bool) return true; } if (rule.object.get("path_rule_list")) |plst| { if (plst == .array) { for (plst.array.items) |prul| { if (ruleTrue(prul, keyz)) return true; } } } return false; }
pub fn siteTrue(conf: cfgz.Conf, keyz: []const u8) bool { if (conf.grup_rule_mapz) |mapz| { if (mapz == .object) { var iter = mapz.object.iterator(); while (iter.next()) |item| { if (ruleTrue(item.value_ptr.*, keyz)) return true; } } } if (conf.site_rule_list) |ruleList| { if (ruleList == .array) { for (ruleList.array.items) |rule| { if (ruleTrue(rule, keyz)) return true; } } } return false; }
